class Demo {
  void tick() {
    fill(0, 0, 0);
    line(0, 0, width - 1, height - 1, 255, 180, 40);
  }
}

class Demo {
  void tick() {
    fill(0, 0, 0);
    int r = height / 3;
    circle(width / 2, height / 2, r, 9, 40, 200, 255);
    circle(width / 2, height / 2, r / 2, 5, 255, 120, 40);
  }
}

class Demo {
  byte bands = 8;

  void defineControls() {
    addControl("bands", bands, 2, 32);
  }

  void tick() {
    for (int y = 0; y < height; y = y + 1) {
      int band = y * bands / height;
      int wave = beatsin(20 + band * 4, t, 255);
      for (int x = 0; x < width; x = x + 1) {
        if (x * 255 / width < wave) {
          setRGB(y * width + x, wave, 60 + band * 20, 255 - wave);
        } else {
          setRGB(y * width + x, 0, 0, 0);
        }
      }
    }
  }
}

class Demo {
  byte lift = 120;
  byte pull = 14;
  byte sparks = 6;

  int dimensions() { return 2; }

  void defineControls() {
    pool(600);
    addControl("lift", lift, 20, 200);
    addControl("pull", pull, 4, 60);
    addControl("sparks", sparks, 1, 12);
  }

  void tick() {
    fade(36);
    emit(width / 2, height - 1, 47152 + beatsin(9, t, 6000), lift * height / 4,
         sparks, 170, scale(beat(4, t), 256));
    gravity(pull * height / 16);
    drag(2);
    step();
    age(1);
    render(170);
  }
}
